// Découpage « intelligent » : par section Markdown, avec en-tête de contexte et mots-clés.
// Un item par document -> un item par chunk, avec un ID de point déterministe.
const cfg = $('Config1').first().json;
const SIZE = cfg.chunk_size;        // taille max d'un chunk (caractères)
const OVERLAP = cfg.chunk_overlap;  // chevauchement quand une section doit être coupée
const MIN_SECTION = 400;            // sections plus courtes : regroupées avec leurs voisines
const TYPE = { cv: 'cv', project: 'project', expertise: 'stack' };
const LABEL = { cv: 'CV', project: 'Projet', stack: 'Stack' };
const KEYWORD_SECTIONS = /^(competences|certifications|technologies couvertes|stack)$/;

// Hash 53 bits (cyrb53) : même texte -> même entier, accepté comme ID par Qdrant.
function hash53(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761);
    h2 = Math.imul(h2 ^ c, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 4294967296 * (2097151 & h2) + (h1 >>> 0);
}

// Minuscules, sans accents ni parenthèses : "Python (langage de programmation)" -> "python".
const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/\(.*?\)/g, ' ').replace(/\s+/g, ' ').trim();

// Lit le Markdown : titre, sous-titre, sections "## ..." et mots-clés.
function parse(text) {
  const lines = text.replace(/\r/g, '').split('\n');
  const title = (lines.find(l => l.startsWith('# ')) || '').replace(/^#\s*/, '').trim();
  const raw = [];
  let current = { name: 'Introduction', lines: [] };
  for (const l of lines) {
    if (l.startsWith('# ')) continue;
    const m = l.match(/^##\s+(.*)/);
    if (m) { raw.push(current); current = { name: m[1].trim(), lines: [] }; }
    else current.lines.push(l);
  }
  raw.push(current);
  const sections = raw.map(s => ({ name: s.name, body: s.lines.join('\n').trim() })).filter(s => s.body);

  const intro = sections.find(s => s.name === 'Introduction');
  const subtitle = intro ? intro.body.split('\n')[0].replace(/\*\*/g, '').trim().slice(0, 120) : '';

  const kw = [];
  for (const s of sections) if (KEYWORD_SECTIONS.test(norm(s.name))) kw.push(...s.body.split(/[,\n]/));
  for (const l of lines) {
    const m = l.match(/^\*\*(stack|technologies?)\*\*\s*:\s*(.*)/i);
    if (m) kw.push(...m[2].split(','));
  }
  const keywords = [...new Set(kw.map(k => k.replace(/^[-*\s]+/, '').replace(/\*\*/g, '').trim())
    .filter(k => k && k.length < 80))];
  return { title, subtitle, sections, keywords };
}

// Coupe une section trop longue entre deux lignes, avec chevauchement.
function splitLong(text) {
  const out = [];
  let cur = '';
  for (const line of text.split('\n')) {
    if (line.length > SIZE) {
      if (cur.trim()) out.push(cur.trim());
      cur = '';
      for (let i = 0; i < line.length; i += SIZE - OVERLAP) out.push(line.slice(i, i + SIZE));
      continue;
    }
    if (cur && (cur + '\n' + line).length > SIZE) {
      out.push(cur.trim());
      cur = cur.slice(-OVERLAP) + '\n' + line;
    } else {
      cur = cur ? cur + '\n' + line : line;
    }
  }
  if (cur.trim()) out.push(cur.trim());
  return out;
}

// Une section = un chunk ; les petites sections voisines sont regroupées (sans dépasser SIZE).
function group(sections) {
  const chunks = [];
  let cur = null;
  for (const s of sections) {
    const block = s.name === 'Introduction' ? s.body : `## ${s.name}\n${s.body}`;
    if (block.length > SIZE) {
      if (cur) chunks.push(cur);
      cur = null;
      splitLong(block).forEach((t, k) => chunks.push({ names: [k ? `${s.name} (suite)` : s.name], text: t }));
      continue;
    }
    const small = cur && (cur.text.length < MIN_SECTION || block.length < MIN_SECTION);
    if (small && (cur.text + '\n\n' + block).length <= SIZE) {
      cur.names.push(s.name);
      cur.text += '\n\n' + block;
    } else {
      if (cur) chunks.push(cur);
      cur = { names: [s.name], text: block };
    }
  }
  if (cur) chunks.push(cur);
  return chunks;
}

const out = [];
$input.all().forEach((item, i) => {
  const file = $('Validate Supabase object').first().json;
  const text = String(item.json.text ?? item.json.data ?? '').trim();
  const asset_type = TYPE[file.kind];
  if (!text || !asset_type) throw new Error('No extractable text or invalid category');

  const document_id = `${file.bucket}/${file.storage_path}`;
  const version = hash53(text).toString(16); // change dès que le contenu change
  const { title: extractedTitle, subtitle, sections, keywords } = parse(text);
  const title = extractedTitle || file.file_name.replace(/\.[^.]+$/, '');
  const docHeader = `[${LABEL[asset_type]}] ${title}${subtitle ? ' — ' + subtitle : ''}`;

  group(sections).forEach((c, idx) => {
    const header = `${docHeader} | Sections : ${c.names.join(', ')}`;
    out.push({
      json: {
        id: hash53(`${document_id}|${version}|${idx}`),
        embed_text: `title: ${header} | text: ${c.text}`,
        payload: {
          document_id, asset_type, title, version, chunk_index: idx,
          sections: c.names, header,
          keywords, keywords_norm: [...new Set(keywords.map(norm))],
          source: 'supabase_storage', source_bucket: file.bucket, source_path: file.storage_path,
          embedding_model: cfg.embedding_model, synthetic: false, text: c.text,
        },
      },
    });
  });
});
return out;

// Assemble chaque chunk avec son vecteur, puis prépare l'upsert Qdrant.
const cfg = $('Config1').first().json;
const points = $input.all().map((item, i) => {
  const c = $('Chunks + IDs').itemMatching(i).json;
  const vector = item.json.embedding && item.json.embedding.values;
  if (!vector || vector.length !== cfg.dimensions) {
    throw new Error(`Embedding invalide pour ${c.payload.document_id} (chunk ${c.payload.chunk_index})`);
  }
  return { id: c.id, vector, payload: c.payload };
});

// Version courante de chaque document, pour supprimer ensuite les anciennes.
const docs = {};
for (const p of points) docs[p.payload.document_id] = p.payload.version;

return [{ json: {
  points,
  docs: Object.entries(docs).map(([document_id, version]) => ({ document_id, version })),
} }];

