const input = $('From Supabase upload').first().json;
const bucket = String(input.bucket ?? '');
const storagePath = String(input.storage_path ?? '');
if (bucket !== 'olivesoft-knowledge') throw new Error('Unexpected storage bucket');
if (!/^(cv|expertise|project)\/[0-9]+\/[a-zA-Z0-9._ -]+\.(pdf|docx|txt|md)$/i.test(storagePath)) throw new Error('Invalid storage path');
const parts = storagePath.split('/');
const fileName = parts.at(-1);
const docId = String(input.doc_id ?? fileName.replace(/\.[^.]+$/, ''));
const version = Number(input.version ?? 1) || 1;
return [{ json: { bucket, storage_path: storagePath, doc_id: docId, version, kind: parts[0], file_name: fileName, extension: fileName.split('.').at(-1).toLowerCase() } }];

const items = $input.all();
let found;
for (let i = 0; i < items.length && !found; i++) {
  for (const [key, value] of Object.entries(items[i].binary ?? {})) {
    if (/(^|\/)word\/document\.xml$/i.test(String(value.fileName ?? key))) { found = { i, key }; break; }
  }
}
if (!found) throw new Error('DOCX has no word/document.xml');
const xml = (await this.helpers.getBinaryDataBuffer(found.i, found.key)).toString('utf8');
const text = xml.replace(/<w:tab\b[^>]*\/>/g, '\t').replace(/<w:br\b[^>]*\/>/g, '\n').replace(/<\/w:p>/g, '\n').replace(/<[^>]+>/g, '').replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n))).replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&').trim();
if (!text) throw new Error('DOCX contains no extractable text');
return [{ json: { data: text } }];
